-- 뉴스저울 Editorial Engine Phase 4 — Persona Registry 시딩 + 로테이션 컬럼
-- 근거: docs/newsjeoul-editorial-engine-architecture.md §7, DEC-003
-- editors 테이블 스키마는 Phase 1에서 이미 생성됨 — 여기서는 로테이션용 컬럼 추가 + 시드 데이터만.
-- 구체적인 100명 페르소나 설계는 별도 진행(DEC-003) — 이건 각 관점(perspective_tag)마다
-- 최소 1명씩 채운 "동작하는 최소 로스터"이다. 나중에 인원을 늘려도 코드는 안 바뀐다.

ALTER TABLE editors ADD COLUMN IF NOT EXISTS last_assigned_at timestamptz;

ON CONFLICT (name, perspective_tag) DO NOTHING; -- 2026-07-11: editors_name_perspective_unique 제약 추가 후(dedup 마이그레이션) 재실행해도 안전
